func icon(name string, class ...string) template.HTML {
	path, ok := iconPaths[name]
	if !ok {
		path = iconPaths["todo"]
	}
	cls := "icon"
	if len(class) > 0 {
		cls += " " + strings.Join(class, " ")
	}
	return template.HTML(`<svg class="` + cls + `" viewBox="0 0 24 24" aria-hidden="true"><path d="` + path + `"/></svg>`)
}
